python -I -c 'import json,pathlib; root=pathlib.Path("/workspace/data/AgentWorldModel-1K"); needles=["Saturday Park Cleanup & Picnic","ParcelTrace API","Marketing Campaign Overview","Tech Growth 2025","firmware_version"];
tasks={};
for line in (root/"gen_tasks.jsonl").open():
 r=json.loads(line)
 for i,t in enumerate(r["tasks"]):
  if any(n in t for n in needles): tasks[(r["scenario"],i)]=t
print("matched tasks",len(tasks));
for k,v in tasks.items(): print(k,v)
vers={}
for line in (root/"gen_verifier.pure_code.jsonl").open():
 r=json.loads(line)
 for i,v in enumerate(r.get("verifiers",r.get("tasks",[]))):
  if (r["scenario"],i) in tasks: vers[(r["scenario"],i)]=v
print("verifier keys",list(vers));
for k,v in vers.items(): print("\n===",k,"===\n",v if isinstance(v,str) else json.dumps(v,indent=2)[:16000])'

